import { useState } from "react";
import axios from "axios";

export default function AddUser() {
  const [name, setName] = useState("");
  const [address, setAddress] = useState("");

  const handleSave = async () => {
    const mobile = localStorage.getItem("mobile");

    // 1️⃣ Check if mobile exists
    if (!mobile) {
      alert("Mobile not found. Please verify OTP first.");
      return;
    }

    // 2️⃣ Check if name and address are entered
    if (!name || !address) {
      alert("Enter all details");
      return;
    }

    try {
      // 3️⃣ Call the correct API endpoint
      const response = await axios.post(
        `http://localhost:8080/otp/addUser?mobile=${mobile}&name=${name}&address=${address}`
      );

      alert(response.data);
      localStorage.removeItem("mobile"); // Clean up after success
      setName("");
      setAddress("");
    } catch (error) {
      // 4️⃣ Detailed error handling
      if (error.response) {
        // Backend returned a response with error status
        alert("Server error: " + error.response.data);
      } else if (error.request) {
        // Request was made but no response
        alert("No response from server. Check backend or CORS.");
      } else {
        // Something else went wrong
        alert("Error: " + error.message);
      }
      console.error(error);
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Add User Details</h2>

      <input
        type="text"
        placeholder="Enter Name"
        value={name}
        onChange={(e) => setName(e.target.value)}
      />

      <input
        type="text"
        placeholder="Enter Address"
        value={address}
        onChange={(e) => setAddress(e.target.value)}
      />

      <p>Mobile: {localStorage.getItem("mobile") || "Not verified"}</p>

      <button onClick={handleSave}>Save User</button>
    </div>
  );
}
